    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The background is the most common color. Non-background border
    # segments form matching pairs on opposite sides.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    def get_runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            color = values[i]
            j = i
            while j + 1 < len(values) and values[j + 1] == color:
                j += 1
            result.append((color, i, j))
            i = j + 1
        return result

    def paint(r, c, color):
        # Keep the colored border segments intact.
        if 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
            out[r][c] = color

    for side_a, side_b, horizontal in (
        (get_runs(grid[0]), get_runs(grid[-1]), True),
        (get_runs([grid[r][0] for r in range(h)]),
         get_runs([grid[r][-1] for r in range(h)]), False),
    ):
        for ca, a0, a1 in side_a:
            for cb, b0, b1 in side_b:
                if ca != cb or abs((a1 - a0) - (b1 - b0)) > 1:
                    continue

                for r in range(h):
                    for c in range(w):
                        mark = grid[r][c]
                        if mark == bg or mark == ca:
                            continue

                        pos = c if horizontal else r
                        if a0 <= pos <= a1:
                            off = pos - a0
                            source = "a"
                        elif b0 <= pos <= b1:
                            off = pos - b0
                            source = "b"
                        else:
                            continue

                        mapped = (b0 if source == "a" else a0) + off
                        out[r][c] = 4

                        # Extend the mark from its position toward its
                        # border segment.
                        if horizontal:
                            if source == "a":
                                for rr in range(r - 1, -1, -1):
                                    paint(rr, c, mark)
                            else:
                                for rr in range(r + 1, h):
                                    paint(rr, c, mark)
                            # Fill the corresponding line at the opposite side.
                            for rr in range(h):
                                paint(rr, mapped, mark)
                        else:
                            if source == "a":
                                for cc in range(c - 1, -1, -1):
                                    paint(r, cc, mark)
                            else:
                                for cc in range(c + 1, w):
                                    paint(r, cc, mark)
                            for cc in range(w):
                                paint(mapped, cc, mark)

    return out
